This enhanced code snippet provides a more complex implementation that demonstrates multi-threading, encapsulation, and error handling for computing an MD5 hash of a specified file.",328,,"[' ```python
import hashlib
import os
import threading

class FileHasher:
    def __init__(self, file_path):
        self.file_path = file_path
        self.hash_object = hashlib.md5()
        self.lock = threading.Lock()

    def process_file(self, chunk):
        with self.lock:
            self.hash_object.update(chunk)

    def compute_hash(self):
        try:
            with open(self.file_path, 'rb') as file:
                while True:
                    chunk = file.read(8192)
                    if not chunk:
                        break
                    self.process_file(chunk)

            return self.hash_object.hexdigest()
        except Exception as e:
            print(f""Error occurred while computing hash: {e}"")
            return None

def threaded_hasher(file_path):
    hasher = FileHasher(file_path)
    hash_thread = threading.Thread(target=hasher.compute_hash)
    hash_thread.start()
    hash_thread.join()

    return hasher.compute_hash()

# Usage example
file_path = 'path_to_your_file'
md5_hash = threaded_hasher(file_path)
print(f""MD5 Hash: {md5_hash}"")
```

