0,"Develop a Python function that calculates the sum of all prime numbers within a given range. The function should accept two integers, start and end, as input parameters and return the sum of all prime numbers between those two values, inclusive. Ensure the function gracefully handles exceptions for invalid inputs such as non-integer arguments or an end value less than the start value.",328,,"['```python
def sum_of_primes(start, end):
    primes = [2]
    if not isinstance(start, int) or not isinstance(end, int):
        raise ValueError(""Both start and end must be integers."")
    if end < start:
        raise ValueError(""End value must be greater than or equal to start value."")

    for num in range(3, end+1):
        is_prime = True
        for i in primes:
            if num % i == 0:
                is_prime = False
                break
            if i > int(num**0.5):
                break

        if is_prime:
            primes.append(num)

    return sum(primes[start-1:])
