from typing import Optional

def get_sequence(filename: str) -> Optional[int]:
    try:
        with open(filename, 'r') as f:
            lines = sorted([line.strip() for line in f])
        if not lines:
            return None
        else:
            sequence_number = int(lines[-1])
            return sequence_number
    except FileNotFoundError:
        print(f""Error: File '{filename}' not found."", file=sys.stderr)
    except ValueError:
        print(f""Error: Sequence number '{lines[-1]}' is not a valid integer."", file=sys.stderr)
    return None
