}

fn print_result(matches: &App, result: (f64, Option<u32>) | f64) {
    match matches.function {
        Operation::Sum => println!(""Sum: {}"", result),
        Operation::Avg => {
            if let Some(count) = matches.value_of(""count"").map(|v| v.parse::<u32>().ok()) {
                println!(""Average: {}"", result / count as f64)
            } else {
                println!(""Error: Could not determine average without a count"")
            }
        }
        Operation::Max => println!(""Maximum: {}"", result),
    }
}
