import json

class Registry:
    def __init__(self):
        self._registry = {}

    def register(self, factory_id, factory_function):
        if not callable(factory_function):
            raise ValueError(""Factory function must be callable"")
        self._registry[factory_id] = factory_function

    def unregister(self, factory_id):
        if factory_id not in self._registry:
            raise KeyError(""Factory ID not found"")
        del self._registry[factory_id]

    def get_factory(self, factory_id):
        if factory_id not in self._registry:
            raise KeyError(""Factory ID not found"")
        return self._registry[factory_id]

class BaseClass:
    pass

class DerivedClass1(BaseClass):
