struct Setting {
    let key: String
    let value: String
}

struct Configuration {
    var settings: [Setting]
    var totalSettings: Int
}

func loadConfiguration(filename: String) -> Int {
    guard let fileHandle = FileHandle(forReadingAtPath: filename),
          let firstLine = fileHandle.readLine() else { return -1 } // Check for file opening errors

    var config = Configuration(settings: [], totalSettings: 0)
    var maxSettings = 100

    // Loop through each line in the file until EOF or maximum number of settings reached
    while !fileHandle.eof && config.totalSettings < maxSettings {
        if let line = fileHandle.readLine() {
            let components = line.split(separator: ""="")
            guard components.count == 2 else { return -2 } // Check for missing equal sign or no value

            let key = String(components[0])
            let value = String(components[1])

            config.settings.append((key, value))
            config.totalSettings += 1
        }
    }

    return config.totalSettings // Return the number of settings loaded
}

let settingsFilePath = ""systemsettings.ini""
if let settings = loadConfiguration(filename: settingsFilePath) {
    print(""Loaded \((settings.count) settings"")
} else {
    print(""Error loading configuration file: \(loadConfiguration(filename: settingsFilePath))"")
}
