from typing import List
import enum
from datetime import datetime

class TaskStatus:
    def __init__(self, task_id: int, status: str, priority: float):
        self.task_id = task_id
        self.status = status
        self.priority = priority

class Status(enum.Enum):
    PENDING = 1
    IN_PROGRESS = 2
    COMPLETED = 3

def generate_task_list(num_tasks: int) -> List[TaskStatus]:
    statuses = [status.value for status in Status]

    def calculate_priority(task_id: int) -> float:
        return datetime.now().timestamp() * 1000 // (task_id + 1)

    tasks = [
        TaskStatus(
            task_id=i,
            status=statuses[i % len(statuses)],
            priority=calculate_priority(i)
        )
        for i in range(1, num_tasks + 1)
    ]

    return tasks
