struct Setting {
    let key: String
    let value: String
}

struct Configuration {
    var totalSettingsCount: Int
    var settings: [Setting]
}

func loadConfiguration(_ filename: String) -> Int {
    guard let fileHandle = FileHandle(forReadingAtPath: filename) else { return -1 } // Check if file can be opened

    let maxSettingsCount = 10 // Maximum number of settings to load
    var currentSettingCount = 0

    while !fileHandle.endOfFile, currentSettingCount < maxSettingsCount {
        guard let line = String(data: fileHandle.readLine()!, encoding: .utf8) else { break } // Check if line can be read

        if let components = line.components(separatedBy: ""=""), components.count == 2 { // Validate key-value format
            let key = components[0].trimmingCharacters(in: .whitespacesAndNewlines)
            let value = components[1].trimmingCharacters(in: .whitespacesAndNewlines)

            settings.append(Setting(key: key, value: value))
            currentSettingCount += 1
        } else { return -2 } // Invalid line format (missing equal sign or no value)
    }

    if fileHandle.endOfFile && currentSettingCount < maxSettingsCount { settings.append(Setting(key: """", value: """")) } // Handle end of file case

    self.totalSettingsCount = currentSettingCount // Set total number of settings loaded
    return 0 // Successful parsing
}

let settings = Configuration()
if let errorCode = loadConfiguration(""systemsettings.ini"") {
    switch errorCode {
        case -1: print(""Error: Could not open file"")
        case -2: print(""Error: Invalid line format in the configuration file"")
        case -3: print(""Error: Maximum number of settings has been exceeded"")
        default: break
    }
} else {
    print(""Loaded \((settings.totalSettingsCount) settings"")
}
