import sys
import hashlib

def file_hash(filename):
    hasher = hashlib.sha256()
    with open(filename, ""rb"") as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()
