import sys
import json
from jsonschema import validate, ValidationError, Draft7Validator, RefResolver
from jsonschema.validators import draft7

def flatten_json(obj, parent_key='', result={}):
    for key, val in obj.items():
        if isinstance(val, dict) or isinstance(val, list):
            for subkey, _ in flatten_json(val, f""{parent_key}{key}"" if parent_key else key).items():
                result[subkey] = _
        else:
            result[f""{parent_key}{key}"" if parent_key else key] = val
    return result

def load_schema(schema_str):
    schema_loader = {
        'http': schema_str,
        '$ref': lambda context, uri: load_schema(uri),
    }
    resolver = RefResolver(schema_loader)
    validator = Draft7Validator(schema=json.loads(schema_str), resolvers=[resolver])
    return validator

def validate_and_flatten(input_file, output_file, schema):
    with open(input_file, 'r') as input_data:
        data = json.load(input_data)

    try:
        validated_data = flatten_json(validate(instance=data, schema=schema), result={})
    except ValidationError as e:
        print(f""Validation error: {e}"")
        raise SystemExit(1)

    with open(output_file, 'w') as output_data:
        json.dump(validated_data, output_data, indent=4)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file> <output_file> <schema>"")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    schema = sys.argv[3]
    validate_and_flatten(input_file, output_file, load_schema(schema))
