0,"Design a software application that merges the features of a rudimentary text-based game and an elementary level editor. This tool should enable users to issue instructions through the command line to steer the game character, traverse through levels, and engage with elements within the game world. Moreover, users must possess the capability to construct and modify levels utilizing a graphical user interface supplied by the program. The level editor should incorporate basic functionalities such as positioning obstacles, adversaries, and power-ups, along with options for saving and loading personalized levels. The game character should feature movement controls and straightforward artificial intelligence for responding to user inputs and environmental objects.",121,,"['```python
import pygame
import sys
from pygame.locals import *

# Game classes and functions
class Game:
    def __init__(self):
        self.level = Level()  # Initialize level object
        self.character = Character(self.level.width // 2, self.level.height // 2)
        self.running = True

    def run(self):
        clock = pygame.time.Clock()
        while self.running:
            self.handle_input()
            self.level.update(self.character)
            self.render()
            clock.tick(60)

    def handle_input(self):
        for event in pygame.event.get():
            if event.type == QUIT:
                self.running = False
            elif event.type == KEYDOWN:
                if event.key == K_UP:
