import pandas as pd
import os
from typing import Dict

def load_excel_sheets(file_path: str) -> Dict[str, pd.DataFrame]:
    dataframes = {}

    try:
        workbook = pd.read_excel(file_path)

        for sheet_name in workbook.keys():
            dataframes[sheet_name] = workbook[sheet_name]

    except FileNotFoundError:
        raise FileNotFoundError(f""The specified file '{file_path}' does not exist."")
    except Exception as e:
        raise ValueError(f""An error occurred while reading the Excel file. Error details: {str(e)}"")

    return dataframes
```
