# Define SHA-256 hash generator function
def sha_256_generator(data):
    hasher = hashlib.sha256(data.encode()).hexdigest()
    return hasher

# Initialize patron database
patrons = {}

# Define functions to handle patron operations
def create_or_update_patron(request):
    if 'id' in request:
        update_patron(request)
    else:
        create_patron(request)

def create_patron(request):
    id = generate_unique_id()
    patron = {**request, 'id': id}
    patrons[id] = patron
    return {'message': 'Patron created successfully'}

def update_patron(request):
    id = request['id']
    if id in patrons:
        patrons[id]['name'] = request['name']
        patrons[id]['email'] = request['email']
        patrons[id]['membership_type'] = request['membership_type']
        return {'message': 'Patron updated successfully'}
    else:
        return {'error': 'Patron not found'}

def delete_patron(request):
    if 'action' in request and request['action'] == 'delete':
        id = request['id']
        if id in patrons:
            del patrons[id]
            return {'message': 'Patron deleted successfully'}
        else:
            return {'error': 'Patron not found'}
    else:
        return {'error': 'Invalid request'}

# Utilities for generating unique IDs and JSON responses
def generate_unique_id():
    return str(uuid.uuid4())

def json_response(message):
    return json.dumps({'response': message})

# Trigger SHA-256 hash generator for each patron operation
def trigger_hash_generator(operation, data):
    hasher = sha_256_generator(data)
    print(f""Hash generated for {operation}: {hasher}"")

# Main function to handle requests and trigger SHA-256 generator as needed
def main():
    while True:
        request = get_request()  # Assuming there's a function to get HTTP requests here
        operation = request['action']
        data = request.get('data', {})

        if operation in ['create', 'update']:
            trigger_hash_generator(operation, data)
            create_or_update_patron(request)
        elif operation == 'delete':
            trigger_hash_generator(operation, data)
            delete_patron(request)

        print(json.dumps(json_response(handle_request(request))))
