            last_line = lines[-1]
            parts = last_line.split("":"")
            if len(parts) > 1:
                sequence_number = int(parts[1].strip())
    except FileNotFoundError:
        print(f""Error: {filename} not found."")
    except ValueError:
        print(""Invalid sequence number format."")
    except IndexError:
        print(""Sequence number extraction failed."")

    return sequence_number
