import subprocess
import os
import time
from typing import List, Optional

class CommandExecutor:
    def __init__(self, timeout: int = 5):
        self.timeout = timeout

    def execute_command(self, command: List[str], cwd: Optional[str] = None) -> str:
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd)

        try:
            output, error = process.communicate(timeout=self.timeout)
        except subprocess.TimeoutExpired:
            process.kill()
            output, error = process.communicate()

        if error:
            raise Exception(f""Command execution failed: {error.decode('utf-8')}"")

        return output.decode('utf-8')

    def run_in_parallel(self, commands: List[List[str]], cdfs: Optional[List[str]] = None) -> dict:
        results = {}

        for index, command in enumerate(commands):
            result_key = f""Result_{index}""

            if cdfs and index < len(cdfs):
                results[result_key] = self.execute_command(command, cwd=cdfs[index])
            else:
                results[result_key] = self.execute_command(command)

            time.sleep(1)

        return results

    def run_in_sequence(self, commands: List[List[str]], cdfs: Optional[List[str]] = None) -> dict:
        results = {}

        for command in commands:
            result_key = f""Result_{commands.index(command)}""

            if cdfs and commands.index(command) < len(cdfs):
                results[result_key] = self.execute_command(command, cwd=cdfs[commands.index(command)])
            else:
                results[result_key] = self.execute_command(command)

        return results

# Example usage of the enhanced CommandExecutor class.
if __name__ == ""__main__"":
    executor_instance = CommandExecutor()

    # Execute a single command with default timeout.
    single_result = executor_instance.execute_command([""ls"", ""-l""])

    # Run commands in parallel.
    parallel_commands = [[""git"", ""status""], [""pwd""]]
    results = executor_instance.run_in_parallel(parallel_commands)

    print(results)

    # Run commands sequentially.
    sequential_commands = [[""git"", ""log"", ""-n1""], [""ls"", ""-l""]]
    results_sequential = executor_instance.run_in_sequence(sequential_commands)

    print(results_sequential)
```']",161,[0],[],True,0,0,0,

