from typing import List
import time
from enum import Enum

class TaskStatus:
    def __init__(self, task_id: int, status: str, priority: int):
        self.task_id = task_id
        self.status = status
        self.priority = priority

class Status(Enum):
    PENDING = 1
    IN_PROGRESS = 2
    COMPLETED = 3

def calculate_priority(task_id: int) -> int:
    return int(time.time() * 1000) // (task_id + 1)

def generate_task_list(num_tasks: int) -> List[TaskStatus]:
    statuses = [status.value for status in Status]

    tasks = [
        TaskStatus(
            task_id=i,
            status=statuses[i % len(statuses)],
            priority=calculate_priority(i)
        )
        for i in range(1, num_tasks + 1)
    ]

    return tasks
