```python
import os
import sys
from urllib.error import URLError, HTTPError
from typing import List, Tuple
import re

def read_file(filename: str) -> List[str]:
    lines = []
    try:
        with open(filename, 'r') as file:
            for line in file:
                lines.append(line.strip())
    except (FileNotFoundError, IsADirectoryError):
        print(f""File '{filename}' not found or is a directory."")
        sys.exit(1)
    return lines

def sort_lines(lines: List[str]) -> List[str]:
    sorted_lines = sorted(lines)
    return sorted_lines

def extract_sequence_number(line: str) -> int:
    match = re.search(r'(\d+):.*', line)
    if not match:
        print(""Error: Unable to parse sequence number."")
        sys.exit(1)

    try:
        return int(match.group(1))
    except (ValueError, IndexError):
        print(""Error: Invalid sequence number format."")
        sys.exit(1)

def main():
    if len(sys.argv) < 2:
        print(""Usage: python script.py [file_path]"")
        sys.exit(1)

    filename = sys.argv[1]
    lines = read_file(filename)
    sorted_lines = sort_lines(lines)
    last_line = sorted_lines[-1]
    sequence_number = extract_sequence_number(last_line)
    print(""Sequence number:"", sequence_number)

if __name__ == ""__main__"":
    main()
