import hashlib
from io import BytesIO

def compute_file_hash(file_path):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):  # reading in chunks of 8kb (8192 bytes)
