data = ""Secret message""
algorithm = 'AES'
encrypted_data = crypto_lib.encrypt(data, algorithm)
decrypted_data = crypto_lib.decrypt(encrypted_data, algorithm)
print(f""Encrypted data: {encrypted_data}"")
print(f""Decrypted data: {decrypted_data}"")
```

