import socket, os

def get_nic_data():
    nic_data = []

    for iface in socket.getaddrinfo(None, None):
        name, family, type_, ip, _ = iface
        if family == socket.AF_INET and type_ == socket.SOCK_DGRAM:
            interface_name = next((i for i in ('eth0', 'wlp2s0', 'eno') if os.path.exists('/sys/class/net/' + i)), None)

            if interface_name is not None and ip:
                nic_data.append({
                    'interface': interface_name,
                    'ip_address': ip,
                })

                # Get gateway and subnet mask from the network interfaces file
                try:
                    with open('/proc/net/dev', 'r') as f:
                        for line in f:
                            if interface_name in line:
                                index = line.split()[0].find(interface_name) + len(interface_name) + 1
                                gateway = line.split()[index + 2]
                                subnet_mask = line.split()[index + 3]
                                nic_data[-1]['gateway'] = gateway
                                nic_data[-1]['subnet_mask'] = subnet_mask
                except Exception as e:
                    print(f""Error: {e}"")

    return nic_data
