import time

class Node:
    def __init__(self, tag_name, id=None, class_name=None):
        self.tag_name = tag_name
        self.id = id
        self.class_name = class_name
        self.children = []

def traverse_dom(node: Node, selector: str):
    """"""Recursively traverse the DOM tree and return elements matching the given selector.""""""
    if selector == node.tag_name or (node.id and node.id == selector) or (node.class_name and node.class_name == selector):
        return [node]

    result = []
    for child in node.children:
        result.extend(traverse_dom(child, selector))

    return result

def get_anagrams_in_list(input_list: list):
    """"""Find unique anagrams within a list of strings.""""""
    start_time = time.time()

    anagram_map = {}

    for string in input_list:
        sorted_string = ''.join(sorted(string))

        if sorted_string not in anagram_map:
            anagram_map[sorted_string] = [string]
        else:
            anagram_map[sorted_string].append(string)

    unique_anagrams_count = len(anagram_map)

    end_time = time.time()
    processing_time_ms = (end_time - start_time) * 1000

    return unique_anagrams_count, processing_time_ms
