import hashlib
import json
import base64
import requests
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad

def aes_encrypt(data, key, iv):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    encrypted = cipher.encrypt(pad(json.dumps(data), AES.block_size))
    return base64.b64encode(encrypted).decode()

def get_headers_and_encrypt(url, key, iv):
    try:
        response = requests.get(url)
        content_length = response.headers['Content-Length']
        content_type = response.headers['Content-Type']

        if content_length and content_type:
            headers_json = {'Content-Length': content_length, 'Content-Type': content_type}
            encrypted_data = aes_encrypt(headers_json, key, iv)
            return encrypted_data.hex()
        else:
            raise ValueError(""Both 'Content-Length' and 'Content-Type' headers are required."")
    except Exception as e:
        return f""Operation failed with error: {str(e)}""
