class TypeRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, type_name, factory_function):
        if type_name in self._registry:
            raise ValueError(f""Type '{type_name}' already registered"")
        self._registry[type_name] = factory_function

    def unregister(self, type_name):
        if type_name not in self._registry:
            raise ValueError(f""Type '{type_name}' not found"")
        del self._registry[type_name]

    def get_factory_function(self, type_name):
        if type_name not in self._registry:
            raise ValueError(f""Type '{type_name}' not found"")
        return self._registry[type_name]

class BaseType:
