def object_parser_generator(type_registry: TypeRegistry):
    def parse_object(string_data: str) -> object:
        parts = string_data.split(':')
        if len(parts) != 2:
            raise ValueError(""Invalid format: expected 'classname: data'"")
        class_type = parts[0]
        factory_function = type_registry.get_factory_function(class_type)
        parsed_class = factory_function(parts[1])
        return parsed_class
    return parse_object
