In the main function, call `loadConfiguration` with ""systemsettings.ini"" as the argument to populate a `Config` variable named 'settings'. Print ""Loaded Y settings"" where Y represents the number of settings in 'settings', or display an error message with the returned error code if loading fails.",121,,"[' Here's the code for the task:

```swift
import Foundation

struct Setting {
    let key: String
    let value: String
}

struct Configuration {
    var totalSettingsCount: Int
    var settings: [Setting]
}

func loadConfiguration(_ file: String) -> Int {
    guard let handle = FileHandle(forReadingAtPath: file) else { return -1 }
    defer { handle.closeFile() }

    var currentSettingsCount = 0
    var settings: [Setting] = []

    while !handle.eof {
        if let line = String(data: handle.readLine()!, encoding: .utf8) {
            let components = line.components(separatedBy: ""="")
            guard components.count == 2 else { return -2 }

            if currentSettingsCount >= MAX_SETTINGS {
                return -3
            }

            let setting = Setting(key: String(components[0]), value: String(components[1]))
            settings.append(setting)
            currentSettingsCount += 1
        }
    }

    let configuration = Configuration(totalSettingsCount: currentSettingsCount, settings: settings)
    return currentSettingsCount
}

let MAX_SETTINGS = 100
var settings: Configuration = loadConfiguration(""systemsettings.ini"")
if settings.totalSettingsCount > 0 {
    print(""Loaded \((settings.totalSettingsCount) settings"")
} else {
    print(""Error loading configuration: \(settings.totalSettingsCount)"")
}
```

