import rsa
from datetime import datetime, timedelta

class SSLCertificate:
    def __init__(self, subject_name, issuer_name):
        self.subject = subject_name
        self.issuer = issuer_name
        self.private_key, self.public_key = rsa.newkeys(2048)
        self.creation_date = datetime.now()
        self.expiration_date = self.creation_date + timedelta(days=365)
        self.timestamp = self.creation_date

    @property
    def is_valid(self):
        return self.expiration_date > datetime.now()

