class Product:
    def __init__(self, name, price, quantity):
        self.name = name
        self.price = float(price)
        self.quantity = int(quantity)

class FileHandler:
    @staticmethod
    def unique_filename(base_name, extension):
        import os
        import re
        count = 1
        while True:
            new_name = f'{base_name}_{count}{extension}'
            if not os.path.exists(new_name) or re.sub(r'\d+', '', new_name) == base_name:
                return new_name
            count += 1

def main():
    n = int(input(""Enter the number of products: ""))
    product_list = [Product(input(), input(), input()) for _ in range(n)]

    with open(FileHandler.unique_filename('products', '.txt'), 'w') as f:
        for prod in product_list:
            f.write(f'{prod.name},{prod.price},{prod.quantity}\n')

    highest_price_product = max(product_list, key=lambda x: x.price)
    print(f""Product with the highest price is {highest_price_product.name}"")

if __name__ == ""__main__"":
    main()
