import random
import string
import hashlib

def generate_mac_address():
    return ':'.join(['%02x' % random.randint(0, 255) for _ in range(6)])

def generate_nic_configurations(nic_count):
    nic_configs = []
    for _ in range(nic_count):
        interface_id = ''.join(random.choices(string.ascii_uppercase + string.digits, k=8))
        mac_address = generate_mac_address()
        status = 'up' if random.random() < 0.7 else 'down'
        nic_configs.append({'interface_id': interface_id, 'mac_address': mac_address, 'status': status})
    return nic_configs

def nic_to_md5(nic):
    mac_bytes = bytes.fromhex(nic['mac_address'].replace(':', ''))
    return hashlib.md5(mac_bytes).hexdigest()

def main():
    num_nics = 10
    nics_with_md5 = []

    nics_with_md5 = [
        {**nic, **{'md5_hash': nic_to_md5(nic)}} for nic in generate_nic_configurations(num_nics)
    ]

    return nics_with_md5

if __name__ == ""__main__"":
    print(main())
