import random
import string

def generate_nmam_pdu(num_pdu):
    def random_string(length=8):
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))

    def random_pdu_type():
        return random.choice(['GET', 'SET', 'PING', 'DISCOVERY'])

    nmam_pdus = []

    for _ in range(num_pdu):
        neid = f""NE-{random_string()}""
        seid = f""SE-{random_string()}""
        pdu_type = random_pdu_type()

        nmam_pdu = {
